const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/meetings',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    deleted_only: 'SOME_BOOLEAN_VALUE',
    'filters[assignee_id]': 'SOME_ARRAY_VALUE',
    'filters[id]': 'SOME_ARRAY_VALUE',
    'filters[query]': 'SOME_STRING_VALUE',
    'filters[search]': 'SOME_STRING_VALUE',
    serializer_view: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/meetings?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&deleted_only=SOME_BOOLEAN_VALUE&filters%5Bassignee_id%5D=SOME_ARRAY_VALUE&filters%5Bid%5D=SOME_ARRAY_VALUE&filters%5Bquery%5D=SOME_STRING_VALUE&filters%5Bsearch%5D=SOME_STRING_VALUE&serializer_view=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

